/**
 * Périodes minimales d'interdiction d'épandage du programme d'actions national
 * nitrates (7e PAN, arrêté du 30 janvier 2023, annexe I, partie I), complétées
 * des renforcements du programme d'actions régional, d'après le jeu de données
 * ouvert du ministère de la Transition écologique, restreint à la région
 * Nouvelle-Aquitaine (code région 75), campagne 2025-2026.
 *
 * `calendarPeriods` provient de la ressource `calendrier_2025_2026.csv`.
 * Colonnes du jeu de données → champs :
 *   code_region → region ;
 *   zone_sud, zone_montagne, zone_ouest, zone_est, calendrier_est_zar → zone
 *     (valeurs « X_VRAI » → true, « X_FAUX » → false, « X_INDIFFERENT » → clé absente) ;
 *   culture_categorie → cropCategory ; culture_sous_categorie → cropSubCategory ;
 *   culture_suivante → followingCrop ; culture_suite → cropSequel ;
 *   culture_type → cropType ; (cropGroups : correspondance Fourmy, vide si non évidente) ;
 *   fertilisant_type_id (0, 1a, 1b, 2, 3) → fertilizerType ("0", "Ia", "Ib", "II", "III") ;
 *   fertilisant_categorie + fertilisant_sous_categorie → fertilizers (« catégorie / sous-catégorie »),
 *     omis quand la ligne vaut pour toutes les sous-catégories du type (voir `fertilizersByType`) ;
 *   date_debut_interdiction → from ; date_fin_interdiction → to (MM-JJ ; campagne 2025-2026) ;
 *   complement_debut → startComplementRef (« Aucun complément » omis) ;
 *   prescription_pan → prescriptionPanRef ; prescription_par → prescriptionParRef
 *     (« Aucune prescription » omis) ; les *Ref sont des indices dans `calendarTexts`
 *     (textes dédoublonnés, voir `periodTexts`).
 * Colonnes non reprises : culture_categorie_superset, culture_sous_categorie_superset
 *   (libellés courts redondants), est_autorise (toujours « f » en région 75), duplicate.
 * Les lignes ne différant que par la sous-catégorie de fertilisant ont été regroupées
 * (1426 lignes du jeu de données → 149 lignes) ; aucune date ne varie
 * à l'intérieur d'un type pour une même culture et une même zone.
 * Les apostrophes doublées du jeu de données (« l''année ») sont rétablies (« l'année »).
 *
 * `communeZones` provient de la ressource `communes.csv` (COG 2024), restreinte à la région 75.
 * Colonnes → champs : code_commune → insee (complété à 5 caractères), nom_commune → name,
 * code_departement (non repris : 2 premiers caractères de insee), est_zone_montagne → montagne,
 * est_zone_vulnerable (« en zone vulnérable » / « partiellement en zone vulnérable » /
 * « hors zone vulnérable ») → zv ("in" / "partial" / "out"),
 * est_zone_ouest (« zone ouest » / « hors zone ouest ») → ouest, est_zar (« en ZAR » /
 * « hors ZAR ») → zar, est_zone_sud → sud, est_zone_est → est ; drapeaux omis quand faux.
 * Attention : le classement ZV de ce fichier est antérieur à l'arrêté Adour-Garonne du
 * 24/08/2026 (voir zoning/adour-garonne-2026.ts, qui fait foi pour ce bassin).
 *
 * Généré : ne pas modifier à la main.
 */
import type { CropGroup, Table } from "../types.js";

export type FertilizerType = "0" | "Ia" | "Ib" | "II" | "III";

/** Zones auxquelles une période s'applique ; clé absente = indifférent. */
export interface CalendarZone {
  sud?: boolean;
  montagne?: boolean;
  ouest?: boolean;
  est?: boolean;
  zar?: boolean;
}

export interface CalendarPeriod {
  /** Code INSEE de la région. */
  region: string;
  zone: CalendarZone;
  cropCategory: string;
  cropSubCategory: string;
  followingCrop?: string;
  cropSequel?: string;
  cropType?: string;
  cropGroups: CropGroup[];
  /** null : ligne « sols non cultivés », tous fertilisants. */
  fertilizerType: FertilizerType | null;
  /** Sous-catégories concernées quand la ligne ne vaut pas pour tout le type. */
  fertilizers?: string[];
  /** Début d'interdiction (MM-JJ). */
  from: string;
  /** Fin d'interdiction (MM-JJ). */
  to: string;
  /** Début et fin identiques (même année) : épandage non interdit selon le jeu de données. */
  noProhibition?: true;
  /** Interdiction toute l'année (du 1er juillet au 1er juillet ou au 30 juin suivant). */
  allYear?: true;
  /** Indice dans `calendarTexts` (colonne complement_debut). */
  startComplementRef?: number;
  /** Indice dans `calendarTexts` (colonne prescription_pan). */
  prescriptionPanRef?: number;
  /** Indice dans `calendarTexts` (colonne prescription_par). */
  prescriptionParRef?: number;
}

/** Drapeaux booléens présents seulement quand ils valent true. Département = 2 premiers caractères de insee. */
export interface CommuneZone {
  insee: string;
  name: string;
  zv: "in" | "partial" | "out";
  montagne?: true;
  ouest?: true;
  zar?: true;
  sud?: true;
  est?: true;
}

