/** Textes d'une période (compléments et prescriptions). */
export function periodTexts(p: CalendarPeriod): { startComplement?: string; prescriptionPan?: string; prescriptionPar?: string } {
  const out: { startComplement?: string; prescriptionPan?: string; prescriptionPar?: string } = {};
  if (p.startComplementRef !== undefined) out.startComplement = calendarTexts[p.startComplementRef];
  if (p.prescriptionPanRef !== undefined) out.prescriptionPan = calendarTexts[p.prescriptionPanRef];
  if (p.prescriptionParRef !== undefined) out.prescriptionPar = calendarTexts[p.prescriptionParRef];
  return out;
}

